SELECT g.* FROM `group` g WHERE g.status = 1 AND g.is_visible = 1 AND (g.group_name LIKE CONCAT('%', #{keyword}, '%') OR CAST(g.id AS CHAR) = #{keyword})
AND DATE(g.create_time) >= #{startDate}
AND DATE(g.create_time) <= #{endDate}
ORDER BY
g.create_time ASC, g.id ASC g.create_time DESC, g.id DESC g.group_name ASC, g.id ASC g.group_name DESC, g.id DESC
CASE WHEN g.group_name = #{keyword} THEN 1 WHEN g.group_name LIKE CONCAT(#{keyword}, '%') THEN 2 ELSE 3 END, g.create_time DESC, g.id DESC
LIMIT #{offset}, #{limit}

